using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

/// <summary>
/// MCP tools that wrap the JSONPlaceholder REST API.
/// Uses constructor injection for HttpClient and ILogger.
/// </summary>
[McpServerToolType]
public class JsonPlaceholderTools(HttpClient httpClient, ILogger<JsonPlaceholderTools> logger)
{
    [McpServerTool, Description("Get a post by its ID from the JSONPlaceholder API.")]
    public async Task<string> GetPost(
        [Description("The post ID (1-100)")] int id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching post {Id}", id);
        var post = await httpClient.GetFromJsonAsync<Post>($"posts/{id}", cancellationToken);
        return $"Title: {post!.Title}\nBody: {post.Body}";
    }

    [McpServerTool, Description("List posts, optionally filtered by user ID.")]
    public async Task<string> ListPosts(
        [Description("Filter by user ID (optional)")] int? userId = null,
        [Description("Max number of posts to return (default 5)")] int limit = 5,
        CancellationToken cancellationToken = default)
    {
        var url = userId.HasValue ? $"posts?userId={userId}" : "posts";
        var posts = await httpClient.GetFromJsonAsync<Post[]>(url, cancellationToken);
        var results = posts!.Take(limit).Select(p => $"[{p.Id}] {p.Title}");
        return string.Join("\n", results);
    }

    [McpServerTool, Description("Get all comments for a specific post.")]
    public async Task<string> GetComments(
        [Description("The post ID to get comments for")] int postId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching comments for post {PostId}", postId);
        var comments = await httpClient.GetFromJsonAsync<Comment[]>(
            $"posts/{postId}/comments", cancellationToken);
        var results = comments!.Select(c => $"{c.Name} ({c.Email}): {c.Body}");
        return string.Join("\n---\n", results);
    }

    [McpServerTool(ReadOnly = true), Description("Get user profile information by user ID.")]
    public async Task<string> GetUser(
        [Description("The user ID (1-10)")] int id,
        CancellationToken cancellationToken = default)
    {
        var user = await httpClient.GetFromJsonAsync<User>($"users/{id}", cancellationToken);
        return $"Name: {user!.Name}\nEmail: {user.Email}\nCompany: {user.Company?.Name}";
    }
}

// DTOs for JSON deserialization
public record Post(
    [property: JsonPropertyName("id")] int Id,
    [property: JsonPropertyName("userId")] int UserId,
    [property: JsonPropertyName("title")] string Title,
    [property: JsonPropertyName("body")] string Body);

public record Comment(
    [property: JsonPropertyName("name")] string Name,
    [property: JsonPropertyName("email")] string Email,
    [property: JsonPropertyName("body")] string Body);

public record User(
    [property: JsonPropertyName("id")] int Id,
    [property: JsonPropertyName("name")] string Name,
    [property: JsonPropertyName("email")] string Email,
    [property: JsonPropertyName("company")] Company? Company);

public record Company(
    [property: JsonPropertyName("name")] string Name);

